import { useEffect, useRef, useState } from 'react';
import { money, send, useApi, type Payment, type User } from './api';

type Item =
  | { kind: 'user'; text: string }
  | { kind: 'assistant'; id: string; text: string; partial?: boolean }
  | { kind: 'tool'; id: string; name: string; done: boolean; error?: boolean }
  | { kind: 'action'; id: string; title: string; data: { paymentId: string; vendor: string; amount: number } }
  | { kind: 'error'; text: string }
  | { kind: 'notice'; text: string };

type Status = 'connecting' | 'live' | 'timeout' | 'done' | 'error';

/** The product's chat transport: SSE from /api/assistant/stream. Stagecraft tapes mock it. */
function useAssistantStream() {
  const [items, setItems] = useState<Item[]>([]);
  const [status, setStatus] = useState<Status>('connecting');
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    setStatus('connecting');
    const es = new EventSource('/api/assistant/stream');
    es.onmessage = (m) => {
      const e = JSON.parse(m.data);
      switch (e.type) {
        case 'hello':
          setItems([]);
          setStatus('live');
          break;
        case 'user_message':
          setItems((xs) => [...xs, { kind: 'user', text: e.text }]);
          break;
        case 'message_start':
          setItems((xs) => [...xs, { kind: 'assistant', id: e.id, text: '' }]);
          break;
        case 'token':
          setItems((xs) => xs.map((x) => (x.kind === 'assistant' && x.id === e.id ? { ...x, text: x.text + e.text } : x)));
          break;
        case 'message_end':
          setItems((xs) => xs.map((x) => (x.kind === 'assistant' && x.id === e.id ? { ...x, partial: e.partial } : x)));
          break;
        case 'tool_call':
          setItems((xs) => [...xs, { kind: 'tool', id: e.id, name: e.name, done: false }]);
          break;
        case 'tool_result':
          setItems((xs) => xs.map((x) => (x.kind === 'tool' && x.id === e.id ? { ...x, done: true, error: e.isError } : x)));
          break;
        case 'pending_action':
          setItems((xs) => [...xs, { kind: 'action', id: e.id, title: e.title, data: e.data }]);
          break;
        case 'error':
          setItems((xs) => [...xs, { kind: 'error', text: e.message }]);
          break;
        case 'timeout':
          if (e.replay) setItems((xs) => [...xs, { kind: 'notice', text: 'A request timed out and was retried.' }]);
          else {
            setStatus('timeout');
            es.close();
          }
          break;
        case 'done':
          setStatus('done');
          break;
      }
    };
    es.onerror = () => {
      setStatus((s) => (s === 'timeout' ? s : 'error'));
      es.close();
    };
    return () => es.close();
  }, [attempt]);
  return { items, status, retry: () => setAttempt((a) => a + 1) };
}

function ActionCard({ item, me }: { item: Extract<Item, { kind: 'action' }>; me: User | null }) {
  const payments = useApi<Payment[]>('/api/payments');
  const [err, setErr] = useState<string | null>(null);
  const p = payments.data?.find((x) => x.id === item.data.paymentId);
  const act = (verb: 'approve' | 'reject') => send('POST', `/api/payments/${item.data.paymentId}/${verb}`).catch((e: Error) => setErr(e.message));
  return (
    <div className="chat__action" data-testid="pending-action">
      <strong>{item.title}</strong>
      <span className="muted">{item.data.vendor} · {money(item.data.amount)}</span>
      {p?.status === 'approved' ? (
        <span className="pill pill--approved">approved</span>
      ) : p?.status === 'rejected' ? (
        <span className="pill pill--rejected">rejected</span>
      ) : me?.role === 'admin' ? (
        <span className="actions">
          <button className="btn" onClick={() => act('approve')}>Approve</button>
          <button className="btn btn--ghost" onClick={() => act('reject')}>Reject</button>
        </span>
      ) : (
        <span className="muted">Waiting for an admin</span>
      )}
      {err && <span className="error">{err}</span>}
    </div>
  );
}

export function Assistant({ onClose, me }: { onClose: () => void; me: User | null }) {
  const { items, status, retry } = useAssistantStream();
  const end = useRef<HTMLDivElement>(null);
  useEffect(() => {
    // Block body on purpose: newer browsers return a Promise from scrollIntoView, and React rejects non-function cleanups.
    end.current?.scrollIntoView({ block: 'end' });
  }, [items]);
  return (
    <aside className="chat" aria-label="Assistant" data-testid="assistant">
      <header className="chat__head">
        <strong>Assistant</strong>
        <button className="btn btn--ghost" onClick={onClose} aria-label="Close assistant">✕</button>
      </header>
      <div className="chat__body" aria-live="polite">
        {items.length === 0 && status !== 'timeout' && <p className="muted">Ask about payments, cards or spend.</p>}
        {items.map((it, i) => {
          switch (it.kind) {
            case 'user':
              return <div key={i} className="chat__msg chat__msg--user">{it.text}</div>;
            case 'assistant':
              return (
                <div key={i} className="chat__msg" data-testid="assistant-message">
                  {it.text}
                  {it.partial && <span className="muted"> …</span>}
                </div>
              );
            case 'tool':
              return <div key={i} className="chat__tool">{it.done ? (it.error ? '✕' : '✓') : '…'} {it.name.replace('_', ' ')}</div>;
            case 'action':
              return <ActionCard key={i} item={it} me={me} />;
            case 'error':
              return <div key={i} role="alert" className="chat__error" data-testid="assistant-error">{it.text}</div>;
            case 'notice':
              return <div key={i} className="chat__notice">{it.text}</div>;
          }
        })}
        {status === 'timeout' && (
          <div className="chat__error" role="alert" data-testid="assistant-timeout">
            The assistant took too long to answer.{' '}
            <button className="btn" onClick={retry}>Retry</button>
          </div>
        )}
        <div ref={end} />
      </div>
      <form className="chat__input" onSubmit={(e) => e.preventDefault()}>
        <input aria-label="Message" placeholder="Message the assistant" />
        <button className="btn">Send</button>
      </form>
    </aside>
  );
}

==> src/pages/AgentControls.tsx <==
import { Variant } from '@stagecraft/react';
import { AGENTS_API, money, send, useApi, type Agent } from '../api';

function Toggle({ agent }: { agent: Agent }) {
  const next = agent.status === 'active' ? 'paused' : 'active';
  return (
    <button className="btn btn--ghost" onClick={() => send('PATCH', `${AGENTS_API}/api/agents/${agent.id}`, { status: next })}>
      {agent.status === 'active' ? 'Pause' : 'Resume'}
    </button>
  );
}

function AgentTable({ agents }: { agents: Agent[] }) {
  return (
    <table className="table" data-testid="agents-table">
      <thead>
        <tr>
          <th scope="col">Agent</th>
          <th scope="col">Can do</th>
          <th scope="col">Spend limit</th>
          <th scope="col">Status</th>
          <th scope="col"><span className="sr-only">Actions</span></th>
        </tr>
      </thead>
      <tbody>
        {agents.map((a) => (
          <tr key={a.id}>
            <td>{a.name}</td>
            <td className="muted">{a.scope}</td>
            <td className="num">{money(a.spendLimit)}</td>
            <td><span className={`pill pill--${a.status}`}>{a.status}</span></td>
            <td><Toggle agent={a} /></td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function AgentCards({ agents }: { agents: Agent[] }) {
  return (
    <div className="cards" data-testid="agents-cards">
      {agents.map((a) => (
        <article key={a.id} className="card">
          <h3>{a.name}</h3>
          <p className="muted">{a.scope}</p>
          <p>Limit {money(a.spendLimit)} · <span className={`pill pill--${a.status}`}>{a.status}</span></p>
          <Toggle agent={a} />
        </article>
      ))}
    </div>
  );
}

export function AgentControls() {
  const { data, error } = useApi<Agent[]>(`${AGENTS_API}/api/agents`);
  if (error) return <p className="error">Could not load agents: {error}</p>;
  if (!data) return <p className="muted">Loading agents…</p>;
  return (
    <>
      <h1>Agent controls</h1>
      <p className="muted">Decide what each AI agent can do with your money.</p>
      {data.length === 0 ? (
        <section className="card empty" data-testid="agents-empty">
          <h2>No agents connected</h2>
          <p>Connect an agent to let it read transactions or draft payments. You set the limits.</p>
          <button className="btn">Connect an agent</button>
        </section>
      ) : (
        <Variant name="agent-list-layout" options={{ table: <AgentTable agents={data} />, cards: <AgentCards agents={data} /> }} />
      )}
    </>
  );
}

==> src/pages/Dashboard.tsx <==
import { useFlag } from '@stagecraft/react';
import { money, useApi, type Account, type Payment } from '../api';

export function Dashboard() {
  const account = useApi<Account>('/api/account');
  const payments = useApi<Payment[]>('/api/payments');
  const limitDisplay = useFlag('limit-display', 'bar');
  if (account.error) return <p className="error">Could not load your account: {account.error}</p>;
  const a = account.data;
  if (!a) return <p className="muted">Loading…</p>;
  const pct = Math.min(100, Math.round((a.spentThisMonth / a.monthlyLimit) * 100));
  return (
    <>
      <h1>{a.name}</h1>
      <div className="grid">
        <section className="card">
          <h2>Balance</h2>
          <p className="big" data-testid="balance">{money(a.balance)}</p>
        </section>
        <section className="card">
          <h2>Monthly limit</h2>
          {limitDisplay === 'bar' ? (
            <div className="meter" role="meter" aria-valuenow={pct} aria-valuemin={0} aria-valuemax={100} aria-label="Monthly limit used">
              <div className={`meter__fill ${pct >= 100 ? 'meter__fill--over' : ''}`} style={{ width: `${pct}%` }} />
            </div>
          ) : null}
          <p data-testid="limit">
            {money(a.spentThisMonth)} of {money(a.monthlyLimit)} ({pct}%)
          </p>
        </section>
      </div>
      <section className="card">
        <h2>Recent payments</h2>
        {payments.data?.length ? (
          <ul className="list">
            {payments.data.slice(0, 5).map((p) => (
              <li key={p.id}>
                <span>{p.vendor}</span>
                <span className={`pill pill--${p.status}`}>{p.status.replace('_', ' ')}</span>
                <span className="num">{money(p.amount)}</span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="muted">No payments yet.</p>
        )}
      </section>
    </>
  );
}

