import { defineHandlers } from '@stagecraft/core';
import type { DB } from './seed';

// Keys are "METHOD /path/:param". Mutate ctx.db to persist writes for the session.
// The assistant chat stream (GET /api/assistant/stream) is served by tapes (see stagecraft.config.ts).
export const handlers = defineHandlers<DB>({
  'GET /api/me': ({ db, persona, reply }) => db.users.find((u) => u.id === persona.userId) ?? reply(401, { error: 'Not signed in' }),

  'GET /api/account': ({ db }) => db.account,

  'GET /api/payments': ({ db }) => [...db.payments].sort((a, b) => b.date.localeCompare(a.date)),

  'POST /api/payments/:id/:action': ({ db, params, persona, reply }) => {
    const { id, action } = params;
    if (action !== 'approve' && action !== 'reject') return reply(404, { error: 'Not found' });
    const p = db.payments.find((x) => x.id === id);
    if (!p) return reply(404, { error: 'Payment not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only an admin can approve or reject payments.' });
    if (db.account.status === 'frozen' && action === 'approve')
      return reply(423, { error: 'This account is frozen. Payments can’t be approved until the review is finished.' });
    if (p.status !== 'pending_approval') return reply(409, { error: `This payment is already ${p.status.replace('_', ' ')}.` });
    p.status = action === 'approve' ? 'approved' : 'rejected';
    return p;
  },

  'POST /api/onboarding/complete-step': ({ db, persona, reply }) => {
    const u = db.users.find((x) => x.id === persona.userId);
    if (!u) return reply(401, { error: 'Not signed in' });
    u.onboardingStep = Math.min(4, u.onboardingStep + 1);
    return u;
  },

  // Served from https://api.ledgerly.example (cross-origin; listed in apiOrigins).
  'GET /api/agents': ({ db }) => db.agents,

  'PATCH /api/agents/:id': ({ db, params, body, persona, reply }) => {
    const a = db.agents.find((x) => x.id === params.id);
    if (!a) return reply(404, { error: 'Agent not found' });
    if (persona.role !== 'admin') return reply(403, { error: 'Only an admin can change agents.' });
    if (body?.status === 'active' || body?.status === 'paused') a.status = body.status;
    return a;
  },
});

